## Microsoft.UI.Xaml.Controls.ScrollingInputKinds  (enum)
type ScrollingInputKinds* = distinct int32
proc `==`*(a, b: ScrollingInputKinds): bool {.borrow.}
proc `or`*(a, b: ScrollingInputKinds): ScrollingInputKinds {.borrow.}
proc `and`*(a, b: ScrollingInputKinds): ScrollingInputKinds {.borrow.}
proc `not`*(a: ScrollingInputKinds): ScrollingInputKinds {.borrow.}
proc contains*(a, b: ScrollingInputKinds): bool =
  ## Is every bit of `b` set in `a`?
  (int32(a) and int32(b)) == int32(b)
proc `$`*(v: ScrollingInputKinds): string =
  ## The set bits by name, or the number if none match.
  var rest = int32(v)
  result = ""
  if (rest and 1'i32) == 1'i32:
    if result.len > 0: result.add " or "
    result.add "Touch"
    rest = rest and not 1'i32
  if (rest and 2'i32) == 2'i32:
    if result.len > 0: result.add " or "
    result.add "Pen"
    rest = rest and not 2'i32
  if (rest and 4'i32) == 4'i32:
    if result.len > 0: result.add " or "
    result.add "MouseWheel"
    rest = rest and not 4'i32
  if (rest and 8'i32) == 8'i32:
    if result.len > 0: result.add " or "
    result.add "Keyboard"
    rest = rest and not 8'i32
  if (rest and 16'i32) == 16'i32:
    if result.len > 0: result.add " or "
    result.add "Gamepad"
    rest = rest and not 16'i32
  if (rest and 255'i32) == 255'i32:
    if result.len > 0: result.add " or "
    result.add "All"
    rest = rest and not 255'i32
  if rest != 0 or result.len == 0:
    if result.len > 0: result.add " or "
    result.add "ScrollingInputKinds(" & $rest & ")"
const ScrollingInputKinds_None* = ScrollingInputKinds(0'i32)
const ScrollingInputKinds_Touch* = ScrollingInputKinds(1'i32)
const ScrollingInputKinds_Pen* = ScrollingInputKinds(2'i32)
const ScrollingInputKinds_MouseWheel* = ScrollingInputKinds(4'i32)
const ScrollingInputKinds_Keyboard* = ScrollingInputKinds(8'i32)
const ScrollingInputKinds_Gamepad* = ScrollingInputKinds(16'i32)
const ScrollingInputKinds_All* = ScrollingInputKinds(255'i32)

